using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Set up options with a default resolver so common types are known.
var options = new JsonSerializerOptions
{
    TypeInfoResolver = JsonSerializerOptions.Default.TypeInfoResolver
};

// ── 1. Strongly-typed metadata retrieval ──
// GetTypeInfo<T>() returns JsonTypeInfo<T> directly — no cast needed.
JsonTypeInfo<int[]> arrayInfo = options.GetTypeInfo<int[]>();
Console.WriteLine($"Type:   {arrayInfo.Type}");
Console.WriteLine($"Kind:   {arrayInfo.Kind}");
Console.WriteLine($"Result: {JsonSerializer.Serialize(new[] { 1, 2, 3 }, arrayInfo)}");

Console.WriteLine();

// ── 2. Probe without throwing ──
// TryGetTypeInfo returns false instead of throwing when metadata isn't available.
if (options.TryGetTypeInfo(typeof(string), out JsonTypeInfo? stringInfo))
    Console.WriteLine($"string metadata found  – Kind: {stringInfo.Kind}");
else
    Console.WriteLine("string metadata NOT found");

// Try a type the resolver doesn't know about (custom class, no source-gen context).
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = JsonTypeInfoResolver.Combine() // empty resolver
};

if (limited.TryGetTypeInfo(typeof(MyRecord), out _))
    Console.WriteLine("MyRecord metadata found");
else
    Console.WriteLine("MyRecord metadata NOT found (expected)");

record MyRecord(string Name);

